using System;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;using AstroGateway.NativeSlice;
namespace AstroGateway.MarsEnvironment {
 [DefaultExecutionOrder(100)]public class EnvironmentPresentation:MonoBehaviour {
 public NativeSliceGame game;public Light sun;public Camera scenic;public EnvironmentPreset[] lighting;public ResearchTarget[] targets;public Transform[] closedAirlocks;public ParticleSystem wheelDust;public Material sky;public int lightIndex=2,quality=1;UniversalRenderPipelineAsset pipeline;RenderPipelineAsset prior;int priorMips,priorCap;float priorLod;public string note="";public bool paused;float priorTimeScale=1;long solarTick=-1;readonly System.Collections.Generic.HashSet<string> linkedScans=new System.Collections.Generic.HashSet<string>();
 public void Initialize(){if(pipeline){QualitySettings.renderPipeline=pipeline;return;}prior=QualitySettings.renderPipeline;priorMips=QualitySettings.globalTextureMipmapLimit;priorCap=Application.targetFrameRate;priorLod=QualitySettings.lodBias;pipeline=Instantiate(game.prototype.previewPipeline);QualitySettings.renderPipeline=pipeline;ApplyQuality(quality);ApplyLighting(lightIndex);}
 void Start(){game.testSave=System.IO.Path.Combine(Application.persistentDataPath,"AstroGateway_MarsResearchBase_v1.json");Initialize();}
 public void ApplyQuality(int q){quality=Mathf.Clamp(q,0,3);if(!pipeline)return;QualitySettings.renderPipeline=pipeline;pipeline.renderScale=new[]{.65f,.8f,1f,1f}[quality];pipeline.mainLightShadowmapResolution=new[]{512,1024,2048,4096}[quality];pipeline.shadowDistance=new[]{25f,45f,65f,90f}[quality];pipeline.msaaSampleCount=new[]{1,2,4,4}[quality];pipeline.supportsHDR=quality>=2;QualitySettings.globalTextureMipmapLimit=new[]{2,1,0,0}[quality];QualitySettings.lodBias=new[]{.65f,1f,1.5f,2f}[quality];Application.targetFrameRate=quality<2?30:60;game.prototype.follow.farClipPlane=quality==0?330:550;game.prototype.follow.GetUniversalAdditionalCameraData().renderPostProcessing=quality>=1;}
 public void ApplyLighting(int i){lightIndex=Mathf.Clamp(i,0,lighting.Length-1);var p=lighting[lightIndex];sun.transform.rotation=Quaternion.Euler(p.sunEuler);sun.color=p.sunColor;sun.intensity=p.intensity;if(sky){sky.SetColor("_Top",p.sky);sky.SetColor("_Horizon",p.horizon);}RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=p.sky*.7f;RenderSettings.ambientEquatorColor=p.horizon*.36f;RenderSettings.ambientGroundColor=new Color(.12f,.09f,.07f);}
 void LateUpdate(){ApplyAtmosphere();}
 public void ApplyAtmosphere(){if(!pipeline)return;var p=lighting[lightIndex];RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=p.horizon;RenderSettings.fogStartDistance=game.prototype.weather==2?10:game.prototype.weather==1?45:90;RenderSettings.fogEndDistance=game.prototype.weather==2?80:game.prototype.weather==1?200:p.fogEnd;var emission=game.prototype.dust.emission;emission.rateOverTime=(game.prototype.weather==0?2:game.prototype.weather==1?14:40)*new[]{.3f,.6f,1f,1.3f}[quality];if(game.prototype.weather==0&&!game.prototype.dust.isPlaying)game.prototype.dust.Play();if(wheelDust){var e=wheelDust.emission;e.rateOverTime=game.prototype.driving?Mathf.Abs(game.prototype.speed)*new[]{1f,2f,4f,6f}[quality]:0;}}
 public void SetPaused(bool value){if(value==paused)return;paused=value;if(value){priorTimeScale=Time.timeScale;Time.timeScale=0;game.touch.Clear();game.modes.Switch(ControlMode.Menu);game.prototype.testMove=Vector2.zero;game.prototype.testLook=Vector2.zero;game.prototype.testBrake=true;game.enabled=false;}else{Time.timeScale=priorTimeScale;game.enabled=true;game.modes.Switch(game.prototype.driving?ControlMode.Rover:ControlMode.Astronaut);}}
 public void AssociateScans(){foreach(var scan in game.scans){if(linkedScans.Contains(scan.sampleId))continue;linkedScans.Add(scan.sampleId);foreach(var target in targets)if(target&&Vector3.Distance(scan.location,target.transform.position)<=3){game.telemetry.Record("research."+target.stableId,"environment.local",1,"simulated_observation",scan.tick);note=target.displayName+" — simulated scan recorded.";break;}}}
 void Update(){if(paused)return;AssociateScans();if(game.tick!=solarTick){solarTick=game.tick;game.telemetry.Record("habitat.solar_availability_index","environment.local",game.prototype.weather==2?.15f:game.prototype.weather==1?.6f:1f,"simulated_index",game.tick);}var k=Keyboard.current;if(k!=null&&k.eKey.wasPressedThisFrame&&Vector3.Distance(game.prototype.ActivePosition(),game.prototype.rover.transform.position)>5){foreach(var target in targets)if(target.TryScan(game)){note=target.displayName+" — simulated scan recorded.";break;}}}
 public string Readback(){return $"scale={pipeline.renderScale} shadow={pipeline.mainLightShadowmapResolution} distance={pipeline.shadowDistance} AA={pipeline.msaaSampleCount} mips={QualitySettings.globalTextureMipmapLimit} lod={QualitySettings.lodBias} cap={Application.targetFrameRate}";}
 void OnDestroy(){if(paused)Time.timeScale=priorTimeScale;if(pipeline){QualitySettings.renderPipeline=prior;QualitySettings.globalTextureMipmapLimit=priorMips;QualitySettings.lodBias=priorLod;Application.targetFrameRate=priorCap;if(Application.isPlaying)Destroy(pipeline);else DestroyImmediate(pipeline);}}
 void OnGUI(){GUILayout.BeginArea(new Rect(14,14,Mathf.Min(210,Screen.safeArea.width*.31f),340),GUI.skin.box);GUILayout.Label(game.registry.displayName+"\nProcedural / simulated prototype");if(closedAirlocks!=null&&System.Array.Exists(closedAirlocks,x=>x&&Vector3.Distance(game.prototype.ActivePosition(),x.position)<4))GUILayout.Label("Airlock sealed — interiors not implemented.");GUILayout.Label("Lighting");for(int i=0;i<lighting.Length;i++)if(GUILayout.Button(lighting[i].label))ApplyLighting(i);GUILayout.Label("Graphics");int q=GUILayout.SelectionGrid(quality,new[]{"Low","Medium","High","Ultra"},2);if(q!=quality)ApplyQuality(q);if(GUILayout.Button(paused?"Resume simulation":"Pause / menu"))SetPaused(!paused);if(GUILayout.Button(scenic.enabled?"Resume gameplay camera":"Scenic camera")){scenic.enabled=!scenic.enabled;game.prototype.follow.enabled=!scenic.enabled;game.modes.Switch(scenic.enabled?ControlMode.Menu:game.prototype.driving?ControlMode.Rover:ControlMode.Astronaut);}GUILayout.Label(note);GUILayout.EndArea();}
 }
}
